parameters.jsCode:
const response = $input.first().json;

// Extraire le texte de la réponse Claude
const rawText = response.content[0].text.trim();

// Parser le JSON retourné par Claude
let parsed;
try {
  // Chercher le JSON dans la réponse (au cas où Claude ajoute du texte)
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON found in Claude response');
  parsed = JSON.parse(jsonMatch[0]);
} catch(e) {
  throw new Error(`Parse error: ${e.message} | Raw: ${rawText.substring(0, 200)}`);
}

// Construire la caption finale (caption + saut de ligne + hashtags)
const fullCaption = `${parsed.caption}\n\n${parsed.hashtags}`;

return [{
  json: {
    caption: parsed.caption,
    hashtags: parsed.hashtags,
    image_prompt: parsed.image_prompt,
    alt_text: parsed.alt_text || '',
    full_caption: fullCaption
  }
}];

const contentData = $('Parse Claude Response').first().json;
const encodedPrompt = encodeURIComponent(contentData.image_prompt);
const imageUrl = 'https://image.pollinations.ai/prompt/' + encodedPrompt + '?width=1080&height=1080&nologo=true&model=flux&seed=' + Date.now();
return [{
  json: {
    image_url: imageUrl,
    full_caption: contentData.full_caption,
    alt_text: contentData.alt_text || ''
  }
}];

const publishResult = $input.first().json;
const container = $('Instagram - Create Container').first().json;

console.log('Post Instagram bebel4881 publié!');
console.log('Container ID:', container.id);
console.log('Post ID:', publishResult.id);

return [{
  json: {
    success: true,
    account: 'bebel4881',
    page: "L'IA qui Bosse",
    container_id: container.id,
    post_id: publishResult.id,
    published_at: new Date().toISOString()
  }
}];
